        // Chỉ seed khi database trống - KHÔNG xóa dữ liệu cũ
        // Nếu đã có dữ liệu, bỏ qua seeding
        if (context.Products.Any() || context.Brands.Any() || context.Categories.Any())
        {
            // Database đã có dữ liệu, không cần seed
            return;
        }

        var now = DateTime.Now;

        // Add sample brands (BrandId will be auto-generated by IDENTITY)
        var brands = new Brand[]
        {
            new Brand { Name = "L'Oréal", Country = "France", IsActive = true, CreatedAt = now, UpdatedAt = now },
            new Brand { Name = "Maybelline", Country = "USA", IsActive = true, CreatedAt = now, UpdatedAt = now },
            new Brand { Name = "MAC Cosmetics", Country = "Canada", IsActive = true, CreatedAt = now, UpdatedAt = now },
            new Brand { Name = "NARS", Country = "France", IsActive = true, CreatedAt = now, UpdatedAt = now },
            new Brand { Name = "Fenty Beauty", Country = "USA", IsActive = true, CreatedAt = now, UpdatedAt = now }
        };

        // Chỉ add brands nếu chưa tồn tại
        var existingBrands = context.Brands.Select(b => b.Name).ToList();
        var newBrands = brands.Where(b => !existingBrands.Contains(b.Name)).ToList();
        if (newBrands.Any())
        {
            context.Brands.AddRange(newBrands);
            context.SaveChanges();
        }

        // Add sample categories (CategoryId will be auto-generated by IDENTITY)
        var categories = new Category[]
        {
            new Category { Name = "Lipstick", Description = "Lipstick products in various finishes", IsActive = true, CreatedAt = now, UpdatedAt = now },
            new Category { Name = "Eye Shadow", Description = "Eye shadow palettes and singles", IsActive = true, CreatedAt = now, UpdatedAt = now },
