        var existingProductNames = context.Products.Select(p => p.Name).ToList();
        var newProducts = products.Where(p => !existingProductNames.Contains(p.Name) && p.BrandId.HasValue && p.CategoryId.HasValue).ToList();
        if (newProducts.Any())
        {
            context.Products.AddRange(newProducts);
            context.SaveChanges();

            // Add product images cho products mới
            var productImages = new List<ProductImage>();
            for (int i = 0; i < newProducts.Count; i++)
            {
                // Products 0-7: Most Loved (lipstick, eyeshadow, blush) - use img-cart-lip
                // Products 8-15: Special Deals (foundation, powder) - use img-cart-brush  
                string imageUrl = i < 8 
                    ? "/public/images/products/img-cart-lip.png" 
                    : "/public/images/products/img-cart-brush.png";
                    
                productImages.Add(new ProductImage
                {
                    ProductId = newProducts[i].ProductId,
                    Url = imageUrl,
                    ImageType = "cover",
                    AltText = newProducts[i].Name,
                    CreatedAt = now
                });
            }

            if (productImages.Any())
            {
                context.ProductImages.AddRange(productImages);
                context.SaveChanges();
            }
        }
